import { index, integer, sqliteTable, text } from 'drizzle-orm/sqlite-core'
import { session, user } from './auth-schema'

// Tables for sign-in (user, session, account, verification, rate limits) are generated by Better Auth:
// `pnpm auth:schema`. Our own tables go below.
export * from './auth-schema'

/** Addresses that bounced or complained (from Resend webhooks). We stop emailing them for a while; see suppression.ts. */
export const emailSuppression = sqliteTable('email_suppression', {
  email: text('email').primaryKey(),
  reason: text('reason').notNull(),
  createdAt: integer('created_at').notNull()
})

/** One row per person: their synced preferences (JSON, validated on read) and when they last changed. */
export const preference = sqliteTable('preference', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  data: text('data').notNull(),
  updatedAt: integer('updated_at').notNull()
})

/** A request to delete an account: it is removed on the scheduled date unless cancelled (then the row is deleted). */
export const accountDeletion = sqliteTable(
  'account_deletion',
  {
    userId: text('user_id')
      .primaryKey()
      .references(() => user.id, { onDelete: 'cascade' }),
    requestedAt: integer('requested_at').notNull(),
    scheduledFor: integer('scheduled_for').notNull(),
    /** SHA-256 of the token in the cancel link, so a leaked database cannot be used to cancel. */
    cancelTokenHash: text('cancel_token_hash').notNull()
  },
  (table) => [index('account_deletion_due_idx').on(table.scheduledFor)]
)

/** A name the person gave one of their sessions ("Work laptop"). Goes with the session or the account. */
export const sessionNickname = sqliteTable('session_nickname', {
  sessionId: text('session_id')
    .primaryKey()
    .references(() => session.id, { onDelete: 'cascade' }),
  userId: text('user_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  nickname: text('nickname').notNull(),
  updatedAt: integer('updated_at').notNull()
})

/** Messages people send from the web app or the desktop app. Removed with the account; included in the data export. */
export const feedback = sqliteTable(
  'feedback',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    kind: text('kind').notNull(),
    message: text('message').notNull(),
    /** The optional diagnostics report (see the desktop app's Settings). */
    diagnostics: text('diagnostics'),
    appVersion: text('app_version'),
    platform: text('platform'),
    source: text('source').notNull(),
    createdAt: integer('created_at').notNull()
  },
  (table) => [index('feedback_user_created_idx').on(table.userId, table.createdAt)]
)
